final class InventarioMemoria implements InventarioRepository
{
    public array $ubicaciones=[1=>['nombre'=>'Laboratorio 1','activa'=>1],2=>['nombre'=>'Laboratorio 2','activa'=>1]];public array $equipos=[];public array $historial=[];
    public function listarEquipos():array{$r=[];foreach($this->equipos as $e)if($e['esta_activo']&&$e['estado_equipo']!=='Baja'){$e['seccion_inventario']=$this->ubicaciones[$e['id_ubicacion']]['nombre'];$r[]=$e;}return $r;}public function ubicacionExiste(int $id,bool $a=false):bool{return isset($this->ubicaciones[$id])&&(!$a||$this->ubicaciones[$id]['activa']);}
    public function crearEquipo(array $d):int{$id=count($this->equipos)+1;$this->equipos[$id]=['id_equipo'=>$id,'nombre_equipo'=>$d['nombre'],'categoria_equipo'=>$d['tipo'],'descripcion'=>$d['observaciones'],'marca_equipo'=>$d['marca'],'cantidad_del_equipo'=>$d['cantidad'],'esta_activo'=>$d['activo'],'estado_equipo'=>$d['estadoBase'],'fecha_agregado'=>'2026-10-19','id_ubicacion'=>$d['seccionId']];$this->historial[]='Alta';return $id;}public function editarEquipo(int $id,array $d):bool{if(!isset($this->equipos[$id])||!$this->equipos[$id]['esta_activo'])return false;foreach(['nombre'=>'nombre_equipo','tipo'=>'categoria_equipo','observaciones'=>'descripcion','marca'=>'marca_equipo','cantidad'=>'cantidad_del_equipo','estado'=>'estado_equipo','seccionId'=>'id_ubicacion'] as $a=>$b)$this->equipos[$id][$b]=$d[$a];$this->historial[]='Modificacion';return true;}public function trasladarEquipo(int $id,int $destino):?bool{if(!isset($this->equipos[$id]))return null;if($this->equipos[$id]['id_ubicacion']===$destino)return false;$this->equipos[$id]['id_ubicacion']=$destino;$this->historial[]='Traslado';return true;}public function bajaEquipo(int $id):?bool{if(!isset($this->equipos[$id]))return null;if(!$this->equipos[$id]['esta_activo'])return false;$this->equipos[$id]['esta_activo']=0;$this->equipos[$id]['estado_equipo']='Baja';$this->historial[]='Baja';return true;}
    public function esquemaUbicacionesActualizado():bool{return true;}public function listarUbicaciones():array{$r=[];foreach($this->ubicaciones as $id=>$u)if($u['activa']){$cantidad=count(array_filter($this->equipos,fn($e)=>$e['id_ubicacion']===$id&&$e['esta_activo']));$r[]=['id_ubicacion'=>$id,'seccion_inventario'=>$u['nombre'],'cantidad_equipos'=>$cantidad];}return $r;}public function crearUbicacion(string $n):int{$id=count($this->ubicaciones)+1;$this->ubicaciones[$id]=['nombre'=>$n,'activa'=>1];return $id;}public function renombrarUbicacion(int $id,string $n):bool{if(!$this->ubicacionExiste($id,true))return false;$this->ubicaciones[$id]['nombre']=$n;return true;}public function bajaUbicacion(int $id,?int $destino):?array{if(!isset($this->ubicaciones[$id]))return null;if(!$this->ubicaciones[$id]['activa'])return ['sinCambios'=>true,'cantidad'=>0];$ids=array_keys(array_filter($this->equipos,fn($e)=>$e['id_ubicacion']===$id&&$e['esta_activo']));if($ids&&$destino===null)throw new \Nexus\Shared\DomainException('Elegi una seccion destino para trasladar los equipos antes de eliminar.');foreach($ids as $e)$this->equipos[$e]['id_ubicacion']=$destino;$this->ubicaciones[$id]['activa']=0;return ['cantidad'=>count($ids),'destino'=>$destino];}
}
function assertInv(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}$r=new InventarioMemoria();$s=new InventarioService($r);$id=$s->altaEquipo(['nombre'=>'Notebook Dell Latitude','tipo'=>'Notebook','observaciones'=>'Equipo docente','marca'=>'Dell','cantidad'=>2,'seccionId'=>1,'estado'=>'Activo']);assertInv($id===1&&$r->historial[0]==='Alta','Alta sin historial.');$s->editarEquipo(1,['nombre'=>'Notebook Dell Latitude 5420','tipo'=>'Notebook','observaciones'=>'Equipo docente','marca'=>'Dell','cantidad'=>2,'seccionId'=>1,'estado'=>'Mantenimiento']);assertInv($r->equipos[1]['estado_equipo']==='Mantenimiento','Edición incompleta.');$s->trasladarEquipo(1,2);assertInv($r->equipos[1]['id_ubicacion']===2,'Traslado falló.');$u=$s->altaUbicacion('Sala de reuniones');$s->renombrarUbicacion($u,'Sala de reuniones 1');assertInv($r->ubicaciones[$u]['nombre']==='Sala de reuniones 1','Renombrado falló.');$resultado=$s->bajaUbicacion(2,1);assertInv($resultado['equiposTrasladados']===1&&$r->equipos[1]['id_ubicacion']===1,'Baja no trasladó equipos.');$s->bajaEquipo(1);assertInv(!$r->equipos[1]['esta_activo']&&end($r->historial)==='Baja','Baja de equipo falló.');echo "OK: 13 comportamientos de inventario verificados.\n";
